    # strokes into the background, on rows where the stroke stops early.
    colors = {}
    for row in grid:
        for value in row:
            colors[value] = colors.get(value, 0) + 1
    background = max(colors, key=colors.get)
    foreground = min((v for v in colors if v != background), default=None)
    if foreground is None:
        return out

    for r, row in enumerate(grid):
