        # Extend a foreground segment that begins at the left edge or is
        # followed by a substantial background tail.
        last = positions[-1]
        if last < w - 1 and last >= w // 3:
            for c in range(last + 1, w):
                if row[c] == background:
                    out[r][c] = 1
    return out
